import { writeFileSync } from "node:fs";
import { BUILT_IN_WORLDS } from "../src/lib/built-in-worlds";
import { routePath, surfaces, surfaceUnder } from "../src/lib/course-graph";
import { isHazard, type WorldDoc } from "../src/lib/worlddoc";

/**
 * Measure every shipped world and write `src/content/course-facts.ts`.
 *
 * `npm run courses:stats`.
 *
 * ── Why a generated file and not a function ──────────────────────────────
 *
 * The same reason `AUTHOR_MS` is a table: the interesting half of this is a
 * Dijkstra over every standable surface in the world, and the guide pages
 * that read it are statically rendered. Running twenty-seven of those inside
 * `next build` would put a solver on the critical path of every deploy to
 * recompute constants that only change when somebody edits a course.
 *
 * `course-facts.test.ts` recomputes all of them and fails with the new value
 * if one drifts, so the table cannot go quietly stale.
 *
 * ── Why these numbers and not others ─────────────────────────────────────
 *
 * Each one has to be true, checkable against the geometry, and *different*
 * between two courses that look alike on a card. "23 jumps, longest 4 cells,
 * climbs 31" distinguishes Spindle from Arc Light; "a hard parkour course"
 * does not. That distinction is the whole reason the guide pages exist.
 */

/** The gap in empty cells between two columns, the unit the courses use. */
const gapCells = (dx: number, dz: number) => Math.max(0, Math.hypot(dx, dz) - 1);

interface Facts {
  slug: string;
  parts: number;
  props: number;
  checkpoints: number;
  hazards: number;
  /** Bounding box of the built geometry, in cells. */
  spanX: number;
  spanZ: number;
  spanY: number;
  /** Route facts. Absent for a world with no goal. */
  route?: {
    steps: number;
    jumps: number;
    longestGap: number;
    biggestRise: number;
    biggestDrop: number;
    climb: number;
    netRise: number;
  };
}

function measure(doc: WorldDoc): Facts {
  const xs = doc.parts.map((p) => p[0]);
  const ys = doc.parts.map((p) => p[1]);
  const zs = doc.parts.map((p) => p[2]);

  const facts: Facts = {
    slug: doc.id,
    parts: doc.parts.length,
    props: doc.props.length,
    checkpoints: doc.checkpoints?.length ?? 0,
    hazards: doc.parts.filter(isHazard).length,
    spanX: Math.max(...xs) - Math.min(...xs) + 1,
    spanZ: Math.max(...zs) - Math.min(...zs) + 1,
    spanY: Math.max(...ys) - Math.min(...ys) + 1,
  };

  if (!doc.goal) return facts;
  const all = surfaces(doc.parts);
  const from = surfaceUnder(doc.spawn, all);
  const to = surfaceUnder(doc.goal, all);
  if (!from || !to) return facts;
  const path = routePath(from, to, all);
  if (!path || path.length < 2) return facts;

  let jumps = 0;
  let longestGap = 0;
  let biggestRise = 0;
  let biggestDrop = 0;
  let climb = 0;

  for (let i = 1; i < path.length; i++) {
    const a = path[i - 1];
    const b = path[i];
    const dx = b.x - a.x;
    const dz = b.z - a.z;
    const rise = b.y - a.y;
    const adjacent = Math.abs(dx) <= 1 && Math.abs(dz) <= 1;
    // Same rule the solver costs by: a step is a walk only when it is next
    // door AND level. Everything else left the ground.
    if (!(adjacent && rise === 0)) {
      jumps++;
      longestGap = Math.max(longestGap, gapCells(dx, dz));
    }
    if (rise > 0) {
      biggestRise = Math.max(biggestRise, rise);
      climb += rise;
    } else if (rise < 0) {
      biggestDrop = Math.max(biggestDrop, -rise);
    }
  }

  facts.route = {
    steps: path.length - 1,
    jumps,
    longestGap: Math.round(longestGap * 10) / 10,
    biggestRise,
    biggestDrop,
    climb,
    netRise: path[path.length - 1].y - path[0].y,
  };
  return facts;
}

const all = BUILT_IN_WORLDS.map((w) => {
  const doc = w.build("user-1");
  process.stdout.write(`  ${w.slug}\n`);
  return measure(doc);
});

const body = all
  .map((f) => {
    const route = f.route
      ? `\n    route: { steps: ${f.route.steps}, jumps: ${f.route.jumps}, longestGap: ${f.route.longestGap}, biggestRise: ${f.route.biggestRise}, biggestDrop: ${f.route.biggestDrop}, climb: ${f.route.climb}, netRise: ${f.route.netRise} },`
      : "";
    return `  ${f.slug.includes("-") ? `"${f.slug}"` : f.slug}: {
    parts: ${f.parts}, props: ${f.props}, checkpoints: ${f.checkpoints}, hazards: ${f.hazards},
    spanX: ${f.spanX}, spanZ: ${f.spanZ}, spanY: ${f.spanY},${route}
  },`;
  })
  .join("\n");

const file = `/**
 * Measured facts about every shipped world, by slug.
 *
 * GENERATED by \`npm run courses:stats\`. Do not edit by hand — run the script.
 *
 * Every number here was read off the geometry the game actually builds: the
 * part counts from the document, the route facts by solving the course and
 * walking the surfaces the solver stood on. That is the point of the file.
 * The guide pages under \`/parkour/<slug>\` are the site's real written
 * content, and written content about a game is worth nothing if its specifics
 * were invented — so none of these were. \`course-facts.test.ts\` recomputes
 * them and fails with the new value if a course is edited and this is not.
 *
 * The route is the SOLVER's route, not a human's: it walks surfaces with no
 * air control and no momentum, so it is a lower bound on the time and an
 * upper bound on what is reachable. A player will take more jumps than
 * \`jumps\` and will not match \`steps\`. What it is sound about is the shape of
 * the course — the longest gap it must cross, how far it climbs, the biggest
 * drop on the way.
 */

export interface RouteFacts {
  /** Moves along the solver's route, walks and jumps together. */
  readonly steps: number;
  /** Moves that left the ground. */
  readonly jumps: number;
  /** Empty cells across the widest gap on the route. */
  readonly longestGap: number;
  /** Tallest single step up, in cells. */
  readonly biggestRise: number;
  /** Longest single fall, in cells. */
  readonly biggestDrop: number;
  /** Every cell gained, summed — the climb if you never came back down. */
  readonly climb: number;
  /** Goal height minus spawn height. */
  readonly netRise: number;
}

export interface WorldFacts {
  readonly parts: number;
  readonly props: number;
  readonly checkpoints: number;
  readonly hazards: number;
  readonly spanX: number;
  readonly spanZ: number;
  readonly spanY: number;
  /** Absent for a world with no goal — a sandbox has no route to solve. */
  readonly route?: RouteFacts;
}

export const WORLD_FACTS: Record<string, WorldFacts> = {
${body}
};

/** Facts for a slug, or undefined for a world that is not one of ours. */
export const factsFor = (slug: string): WorldFacts | undefined =>
  WORLD_FACTS[slug];
`;

writeFileSync("src/content/course-facts.ts", file);
process.stdout.write(`\nWrote src/content/course-facts.ts (${all.length} worlds)\n`);
